#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long n, k;
    cin >> n >> k;
    vector<long long> a(n);
    for (auto &x : a) cin >> x;
    sort(a.begin(), a.end());
    long long m = n / 3, answer = a[n - m] - a[m - 1];
    // side 0: negated smallest third (raising -x lowers x); side 1: largest third
    vector<vector<long long>> sides(2);
    for (long long i = m - 1; i >= 0; i--) sides[0].push_back(-a[i]);
    for (long long i = n - m; i < n; i++) sides[1].push_back(a[i]);
    auto countAtMost = [&](int side, long long level) {
        auto &b = sides[side];
        return (long long)(upper_bound(b.begin(), b.end(), level) - b.begin());
    };
    // (group size = cost per unit, side, current level of that extreme)
    priority_queue<tuple<long long, int, long long>, vector<tuple<long long, int, long long>>, greater<>> heap;
    for (int side = 0; side < 2; side++) heap.push({countAtMost(side, sides[side][0]), side, sides[side][0]});
    while (k && !heap.empty()) {
        auto [count, side, level] = heap.top();
        heap.pop();
        auto &b = sides[side];
        long long distance = count < m ? b[count] - level : k + 1;
        long long increase = min(distance, k / count);
        answer += increase;
        k -= increase * count;
        if (increase < distance) break;
        level += increase;
        heap.push({countAtMost(side, level), side, level});
    }
    cout << answer << "\n";
}

import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int s = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, s, pos - s);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    static int upperBound(long[] b, long level) {
        int lo = 0, hi = b.length;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (b[mid] <= level) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt();
        long k = nextLong();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        Arrays.sort(a);
        int m = n / 3;
        long answer = a[n - m] - a[m - 1];
        // side 0: negated smallest third (raising -x lowers x); side 1: largest third
        long[][] sides = new long[2][m];
        for (int i = 0; i < m; i++) {
            sides[0][i] = -a[m - 1 - i];
            sides[1][i] = a[n - m + i];
        }
        // entries {group size = cost per unit, side, current level of that extreme}
        PriorityQueue<long[]> heap = new PriorityQueue<>((x, y) -> {
            for (int i = 0; i < 3; i++) if (x[i] != y[i]) return Long.compare(x[i], y[i]);
            return 0;
        });
        for (int side = 0; side < 2; side++)
            heap.add(new long[] {upperBound(sides[side], sides[side][0]), side, sides[side][0]});
        while (k > 0 && !heap.isEmpty()) {
            long[] top = heap.poll();
            long count = top[0], level = top[2];
            int side = (int) top[1];
            long[] b = sides[side];
            long distance = count < m ? b[(int) count] - level : k + 1;
            long increase = Math.min(distance, k / count);
            answer += increase;
            k -= increase * count;
            if (increase < distance) break;
            level += increase;
            heap.add(new long[] {upperBound(b, level), side, level});
        }
        System.out.println(answer);
    }
}

package main

import (
	"container/heap"
	"fmt"
	"io"
	"os"
	"sort"
)

var data []byte
var p int

func next() []byte {
	for p < len(data) && data[p] <= ' ' {
		p++
	}
	s := p
	for p < len(data) && data[p] > ' ' {
		p++
	}
	return data[s:p]
}

func nextInt() int64 {
	t := next()
	neg := len(t) > 0 && t[0] == '-'
	if neg {
		t = t[1:]
	}
	var r int64
	for _, c := range t {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

// item: group size (cost per unit), side, current level of that extreme
type item [3]int64
type minHeap []item

func (h minHeap) Len() int { return len(h) }
func (h minHeap) Less(i, j int) bool {
	for t := 0; t < 3; t++ {
		if h[i][t] != h[j][t] {
			return h[i][t] < h[j][t]
		}
	}
	return false
}
func (h minHeap) Swap(i, j int) { h[i], h[j] = h[j], h[i] }
func (h *minHeap) Push(x any)   { *h = append(*h, x.(item)) }
func (h *minHeap) Pop() any {
	old := *h
	x := old[len(old)-1]
	*h = old[:len(old)-1]
	return x
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	k := nextInt()
	a := make([]int64, n)
	for i := range a {
		a[i] = nextInt()
	}
	sort.Slice(a, func(i, j int) bool { return a[i] < a[j] })
	m := n / 3
	answer := a[n-m] - a[m-1]
	// side 0: negated smallest third (raising -x lowers x); side 1: largest third
	sides := [2][]int64{make([]int64, m), make([]int64, m)}
	for i := 0; i < m; i++ {
		sides[0][i] = -a[m-1-i]
		sides[1][i] = a[n-m+i]
	}
	upper := func(b []int64, level int64) int64 {
		return int64(sort.Search(len(b), func(i int) bool { return b[i] > level }))
	}
	h := &minHeap{}
	for side := 0; side < 2; side++ {
		*h = append(*h, item{upper(sides[side], sides[side][0]), int64(side), sides[side][0]})
	}
	heap.Init(h)
	for k > 0 && h.Len() > 0 {
		top := heap.Pop(h).(item)
		count, side, level := top[0], top[1], top[2]
		b := sides[side]
		distance := k + 1
		if count < int64(m) {
			distance = b[count] - level
		}
		increase := min(distance, k/count)
		answer += increase
		k -= increase * count
		if increase < distance {
			break
		}
		level += increase
		heap.Push(h, item{upper(b, level), side, level})
	}
	fmt.Println(answer)
}
